def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_cnf(n):
        clauses = []
        for _ in range(2**n):
            clause = [random.choice([-1, 1]) * (i + 1) for i in range(n)]
            if all(c == 0 for c in clause):
                continue
            clauses.append(clause)
        return clauses

    def dpll_length(cnf):
        n = len(cnf[0])
        stack = []
        assignment = [None] * (n + 1)

        def backtrack():
            while True:
                if not stack:
                    return len(assignment) - 1
                i, j = stack.pop()
                if assignment[j] is None:
                    assignment[j] = 1
                    for clause in cnf:
                        if all(x == 0 or (x > 0 and assignment[x] == 1) or (x < 0 and assignment[-x] == -1) for x in clause):
                            break
                    else:
                        stack.append((i, j + 1))
                        continue
                assignment[j] = -assignment[j]
                if all(x == 0 or (x > 0 and assignment[x] == 1) or (x < 0 and assignment[-x] == -1) for x in clause):
                    stack.append((i, j + 1))
                else:
                    stack.append((i, j + 1))
            return len(assignment) - 1

        return backtrack()

    def minimal_rank(cnf):
        n = len(cnf[0])
        rank = 0
        for i in range(n):
            if all(x == 0 or (x > 0 and assignment[x] == 1) or (x < 0 and assignment[-x] == -1) for x in cnf):
                rank += 1
        return rank

    n = random.randint(5, 40)
    cnf = generate_cnf(n)
    dpll_len = dpll_length(cnf)
    min_rank = minimal_rank(cnf)

    if dpll_len == 0:
        return {
